<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Manage Levels</title><?php include __DIR__ . '/styles_and_scripts.html'; ?></head>
<body><a class="skip-link" href="#main-content">Skip to editor content</a><?php require_once dirname(__DIR__) . '/content/shared-shell.php'; curriculum_render_editor_header(); ?>
<main id="main-content" class="container editor-main py-4">
<?php curriculum_render_editor_hero('Level Management', 'Add, archive, restore, and order curriculum levels', 'Creating a level adds the appropriate starter courses. Archiving preserves all related history and learning-experience links.'); curriculum_render_editor_actions('Management actions', array(array('href' => 'index.php', 'label' => 'Editor Dashboard', 'icon' => 'bi bi-grid-3x3-gap', 'class' => 'btn btn-outline-secondary'))); ?>
<div id="levelStatus" class="editor-save-dialog editor-status mb-3" aria-live="polite"></div>
<section class="editor-panel mb-4"><div class="editor-panel-header editor-panel-header-level"><h2 class="h4 mb-0">Add a Level</h2></div><div class="editor-panel-body"><form id="createLevelForm" class="editor-form-grid">
<label class="form-label" for="program">Program</label><select id="program" name="program" class="form-select"><option value="part_time">Part-time</option><option value="full_time">Full-time</option></select>
<label class="form-label" for="level_name">Level name</label><input id="level_name" name="level_name" class="form-control" required>
<label class="form-label" for="level_short_name">Short name</label><input id="level_short_name" name="level_short_name" class="form-control" required pattern="[A-Za-z0-9_-]{1,32}">
<label class="form-label" for="level_descriptor">Descriptor</label><textarea id="level_descriptor" name="level_descriptor" class="form-control" rows="4"></textarea>
<div id="templateField"><label class="form-label" for="template_level_id">Full-time course-title template</label><select id="template_level_id" name="template_level_id" class="form-select"><option value="">Choose a level</option><?php while ($template = $templates->fetch_assoc()) { ?><option value="<?php echo (int) $template['level_id']; ?>"><?php echo htmlspecialchars($template['level_name'], ENT_QUOTES, 'UTF-8'); ?></option><?php } ?></select><div class="form-text">Copies only the four course titles; all course content and links start blank.</div></div>
<div class="form-check"><input class="form-check-input" type="checkbox" id="active" name="active" checked><label class="form-check-label" for="active">Publish immediately</label></div><button class="btn btn-primary" type="submit">Create Level</button></form></div></section>
<section class="editor-panel"><div class="editor-panel-header editor-panel-header-course"><h2 class="h4 mb-0">Existing Levels</h2></div><div class="editor-panel-body"><div class="table-responsive"><table class="table"><thead><tr><th>Program</th><th>Level</th><th>Status</th><th>Order</th><th>Actions</th></tr></thead><tbody><?php while ($level = $levels->fetch_assoc()) { $isActive = ((int) $level['active'] === 1); ?><tr><td><?php echo $level['program'] === 'part_time' ? 'Part-time' : 'Full-time'; ?></td><td><?php echo htmlspecialchars($level['level_name'], ENT_QUOTES, 'UTF-8'); ?></td><td><?php echo $isActive ? 'Published' : 'Archived'; ?></td><td><?php echo (int) $level['level_order']; ?></td><td class="d-flex gap-2"><a class="btn btn-outline-secondary btn-sm" href="level-edit.php?level_id=<?php echo (int) $level['level_id']; ?>">Edit</a><button class="btn btn-outline-secondary btn-sm" data-action="move" data-direction="up" data-level-id="<?php echo (int) $level['level_id']; ?>">Up</button><button class="btn btn-outline-secondary btn-sm" data-action="move" data-direction="down" data-level-id="<?php echo (int) $level['level_id']; ?>">Down</button><button class="btn btn-<?php echo $isActive ? 'outline-danger' : 'outline-success'; ?> btn-sm" data-action="<?php echo $isActive ? 'archive' : 'restore'; ?>" data-level-id="<?php echo (int) $level['level_id']; ?>"><?php echo $isActive ? 'Archive' : 'Restore'; ?></button></td></tr><?php } ?></tbody></table></div></div></section></main>
<?php curriculum_render_footer(array('path_prefix' => '..', 'profile_path' => 'editors/profile-editor.php', 'include_bootstrap_bundle' => false)); ?>
<script>const statusEl=document.getElementById('levelStatus');function show(message,ok){statusEl.className='editor-save-dialog '+(ok?'alert alert-success':'alert alert-danger');statusEl.textContent=message;}async function action(data){const response=await fetch('level-actions.php',{method:'POST',body:data});const result=await response.json();show(result.message,result.ok);if(result.ok){window.setTimeout(()=>location.reload(),450);}}document.getElementById('program').addEventListener('change',e=>{document.getElementById('templateField').hidden=e.target.value!=='full_time';});document.getElementById('templateField').hidden=true;document.getElementById('createLevelForm').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);data.set('action','create');data.set('active',document.getElementById('active').checked?'1':'0');action(data);});document.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.action==='archive'&&!confirm('Archive this level and all of its courses? Learning-experience links will be retained.'))return;const data=new FormData();data.set('action',button.dataset.action);data.set('level_id',button.dataset.levelId);if(button.dataset.direction)data.set('direction',button.dataset.direction);action(data);}));</script></body></html>
